#[derive(Debug)]
enum AppError {
    Database(rusqlite::Error),
    NotFound,
    Forbidden,
    BadRequest,
}
impl From<rusqlite::Error> for AppError {
    fn from(error: rusqlite::Error) -> Self {
        Self::Database(error)
    }
}
impl IntoResponse for AppError {
    fn into_response(self) -> Response {
        let (status, title, message) = match self {
            Self::Database(error) => {
                eprintln!("Database error: {error}");
                (
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "Something went wrong",
                    "Please try again. Your saved quizzes are still here.",
                )
            }
            Self::NotFound => (
                StatusCode::NOT_FOUND,
                "Page not found",
                "This quiz or question may have been deleted.",
            ),
            Self::Forbidden => (
                StatusCode::FORBIDDEN,
                "Please reload the form",
                "This form has expired. Reload the page and try again.",
            ),
            Self::BadRequest => (
                StatusCode::BAD_REQUEST,
                "Invalid request",
                "Please go back and try again.",
            ),
        };
        (status, Html(views::error_page(title, message))).into_response()
    }
}

#[derive(Debug, Serialize)]
struct Quiz {
    id: i64,
    title: String,
}
#[derive(Debug, Clone, Serialize)]
struct Choice {
    text: String,
    correct: bool,
}
#[derive(Debug, Serialize)]
struct Question {
    id: i64,
    text: String,
    active: bool,
    options: Vec<Choice>,
}
#[derive(Debug)]
struct QuestionInput {
    text: String,
    active: bool,
    options: Vec<Choice>,
}

impl QuestionInput {
    fn blank() -> Self {
        Self {
            text: String::new(),
            active: true,
            options: vec![
                Choice {
                    text: String::new(),
                    correct: false
                };
                4
            ],
        }
    }
    fn from_fields(fields: &Fields) -> Self {
        let mut numbered: Vec<(usize, Choice)> = fields
            .iter()
            .filter_map(|(key, text)| {
                let n = key.strip_prefix("option_")?.parse::<usize>().ok()?;
                Some((
                    n,
                    Choice {
                        text: text.clone(),
                        correct: fields.contains_key(&format!("correct_{n}")),
                    },
                ))
            })
            .collect();
        numbered.sort_by_key(|(n, _)| *n);
        Self {
            text: fields.get("question").cloned().unwrap_or_default(),
            active: fields.contains_key("active"),
            options: numbered.into_iter().map(|(_, choice)| choice).collect(),
        }
    }
    fn saved_options(&self) -> Vec<Choice> {
        self.options
            .iter()
            .filter(|o| !o.text.trim().is_empty())
            .map(|o| Choice {
                text: o.text.trim().to_owned(),
                correct: o.correct,
            })
            .collect()
    }
    fn errors(&self) -> Vec<&'static str> {
        let mut errors = Vec::new();
        let options = self.saved_options();
        if self.text.trim().is_empty() {
            errors.push("Question is required");
        }
        if options.len() < 2 {
            errors.push("Add at least two options");
        }
        if !options.iter().any(|o| o.correct) {
            errors.push("Mark at least one option as correct");
        }
        errors
    }
}

