async fn edit_question(
    State(app): State<AppState>,
    Path((quiz_id, question_id)): Path<(i64, i64)>,
) -> AppResult<Html<String>> {
    let db = app.db.lock().unwrap();
    let quiz = get_quiz(&db, quiz_id)?;
    let q = get_question(&db, quiz_id, question_id)?;
    let input = QuestionInput {
        text: q.text,
        active: q.active,
        options: q.options,
    };
    Ok(Html(views::question_form(
        &app,
        &quiz,
        Some(question_id),
        &input,
        &[],
    )))
}
fn save_question(
    app: &App,
    quiz_id: i64,
    question_id: Option<i64>,
    fields: Fields,
) -> AppResult<Response> {
    verify_csrf(app, &fields)?;
    let input = QuestionInput::from_fields(&fields);
    let mut db = app.db.lock().unwrap();
    let quiz = get_quiz(&db, quiz_id)?;
    if let Some(id) = question_id {
        get_question(&db, quiz_id, id)?;
    }
    let errors = input.errors();
    if !errors.is_empty() {
        return Ok((
            StatusCode::UNPROCESSABLE_ENTITY,
            Html(views::question_form(
                app,
                &quiz,
                question_id,
                &input,
                &errors,
            )),
        )
            .into_response());
    }
    let tx = db.transaction()?;
    let id = if let Some(id) = question_id {
        tx.execute(
            "UPDATE questions SET text=?, active=? WHERE id=? AND quiz_id=?",
            params![input.text.trim(), input.active, id, quiz_id],
        )?;
        tx.execute("DELETE FROM options WHERE question_id=?", [id])?;
        id
    } else {
        tx.execute("INSERT INTO questions(quiz_id,text,active,position) VALUES (?1,?2,?3,(SELECT COALESCE(MAX(position),0)+1 FROM questions WHERE quiz_id=?1))", params![quiz_id, input.text.trim(), input.active])?;
        tx.last_insert_rowid()
    };
    for (i, choice) in input.saved_options().iter().enumerate() {
        tx.execute(
            "INSERT INTO options(question_id,text,correct,position) VALUES (?,?,?,?)",
            params![id, choice.text, choice.correct, i as i64],
        )?;
    }
    tx.commit()?;
    Ok(Redirect::to(&quiz_url(quiz_id)).into_response())
}
