        db.execute("UPDATE questions SET position=-1 WHERE id=?", [first_questions[1].id]).unwrap();
        let mut reordered = expected.clone();
        reordered["questions"].as_array_mut().unwrap().swap(0, 1);
        assert_eq!(serde_json::to_value(QuizContents::load(&db, first).unwrap()).unwrap(), reordered);
        assert_eq!(serde_json::to_value(QuizContents::load(&db, second).unwrap()).unwrap(), expected);
        let third = QuizContents::parse(&reordered.to_string()).unwrap().insert(&mut db).unwrap();
        assert_eq!(serde_json::to_value(QuizContents::load(&db, third).unwrap()).unwrap(), reordered);
