        let id = contents.insert(&mut db).unwrap();
        assert_eq!(serde_json::to_value(QuizContents::load(&db, id).unwrap()).unwrap(), json!({"title":"Empty","questions":[]}));
        assert_eq!(QuizContents::parse(r#"{"title":" \t\n","questions":[]}"#).unwrap_err(), ["Title is required"]);
    }
